begin;
do $$
declare actor uuid:=gen_random_uuid();other_actor uuid:=gen_random_uuid();game uuid;revision uuid;challenge uuid:=gen_random_uuid();second uuid:=gen_random_uuid();upload uuid:=gen_random_uuid();submission uuid:=gen_random_uuid();job jsonb;result jsonb;encrypted jsonb:='{"version":1,"iv":"aaaaaaaaaaaaaaaa","tag":"aaaaaaaaaaaaaaaaaaaaaaaa","ciphertext":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}';i integer;
begin
 insert into auth.users(id,email,email_confirmed_at) values(actor,'auth-confirmed@example.test',now()),(other_actor,'other-auth@example.test',now());
 perform public.distribution_developer_profile(actor,jsonb_build_object('firstName','Fixture','lastName','Pro','contactEmail','Professional@Example.test','publicName','Studio','website',null,'otherContact',null));
 perform public.distribution_developer_profile(other_actor,jsonb_build_object('firstName','Other','lastName','Pro','contactEmail','other-professional@example.test','publicName','Other studio','website',null,'otherContact',null));
 select email_revision into revision from developer_contacts where user_id=actor;
 if (public.distribution_developer_email_status(actor)->>'verified')::boolean then raise exception 'Auth a confirmé le profil professionnel';end if;
 game:=public.distribution_register_game(actor,gen_random_uuid(),'Professional fixture');
 begin perform public.distribution_require_verified_email(actor);raise exception 'Adresse non vérifiée acceptée';exception when raise_exception then if sqlerrm<>'developer_email_unverified' then raise;end if;end;
 begin insert into game_build_uploads(game_id,created_by,request_id,version,status,expected_size,policy,expires_at) values(game,actor,gen_random_uuid(),'1.0.0','queued',100,'{}',now()+interval '1 day');raise exception 'Trigger contourné';exception when raise_exception then if sqlerrm<>'developer_email_unverified' then raise;end if;end;
 set local role service_role;
 result:=public.distribution_reserve_developer_email(actor,challenge,revision,repeat('a',64),repeat('b',64),encrypted);
 perform public.distribution_reserve_developer_email(actor,challenge,revision,repeat('a',64),repeat('c',64),encrypted||'{"ciphertext":"different-but-not-applied"}');
 if (select count(*) from developer_email_challenges where user_id=actor)<>1 or (select code_hash from developer_email_challenges where id=challenge)<>repeat('b',64) then raise exception 'Réservation dupliquée ou remplacée';end if;
 if public.distribution_confirm_developer_email(other_actor,challenge,repeat('b',64))->>'verified'<>'false' then raise exception 'Code d’un autre compte accepté';end if;
 for i in 1..5 loop perform public.distribution_confirm_developer_email(actor,challenge,repeat('c',64));end loop;
 if (select attempts from developer_email_challenges where id=challenge)<>5 or public.distribution_confirm_developer_email(actor,challenge,repeat('b',64))->>'code'<>'verification_locked' then raise exception 'Essais non bornés';end if;
 begin perform public.distribution_reserve_developer_email(actor,second,revision,repeat('a',64),repeat('b',64),encrypted);raise exception 'Renvoi trop rapide';exception when raise_exception then if sqlerrm<>'rate_limited' then raise;end if;end;
 reset role;
 update developer_email_challenges set created_at=clock_timestamp()-interval '61 seconds' where id=challenge;
 set local role service_role;
 perform public.distribution_reserve_developer_email(actor,second,revision,repeat('a',64),repeat('b',64),encrypted);
 reset role;
 update developer_email_challenges set expires_at=clock_timestamp()-interval '1 second' where id=second;
 set local role service_role;
 if public.distribution_confirm_developer_email(actor,second,repeat('b',64))->>'code'<>'verification_expired' then raise exception 'Code expiré accepté';end if;
 reset role;
 update developer_email_challenges set created_at=clock_timestamp()-interval '61 seconds',expires_at=clock_timestamp()+interval '10 minutes' where id=second;
 set local role service_role;
 result:=public.distribution_confirm_developer_email(actor,second,repeat('b',64));
 if result->>'verified'<>'true' then raise exception 'Confirmation valide refusée';end if;
 if public.distribution_confirm_developer_email(actor,second,repeat('b',64))->>'verified'<>'false' then raise exception 'Code consommé rejoué';end if;
 perform public.distribution_require_verified_email(actor);
 insert into game_build_uploads(id,game_id,created_by,request_id,version,status,expected_size,policy,expires_at) values(upload,game,actor,gen_random_uuid(),'1.0.0','queued',100,'{"revision":"1","maxAttempts":3}',now()+interval '1 day');
 insert into game_submissions(id,name_or_studio,email,game_title,demo_url,game_type,description,build_upload_id) values(submission,'Studio','ignored@example.test','Professional fixture','https://example.test','web','Description',upload);
 if not exists(select 1 from game_submission_notifications where submission_id=submission and event_key='received' and notification->>'recipient'='professional@example.test' and recipient_revision=revision and developer_user_id=actor) then raise exception 'Destinataire professionnel absent';end if;
 job:=public.distribution_claim_submission_email(submission);perform public.distribution_prepare_submission_email((job->>'id')::uuid,(job->>'lease')::uuid,'{"text":"internal unchanged"}');perform public.distribution_finish_submission_email((job->>'id')::uuid,(job->>'lease')::uuid,true);
 job:=public.distribution_claim_submission_email_events(submission);
 perform public.distribution_prepare_submission_email((job->>'id')::uuid,(job->>'lease')::uuid,'{"text":"confidential frozen"}');
 begin update developer_contacts set contact_email='next@example.test' where user_id=actor;raise exception 'Adresse modifiée pendant un envoi';exception when raise_exception then if sqlerrm<>'email_delivery_in_progress' then raise;end if;end;
 perform public.distribution_finish_submission_email((job->>'id')::uuid,(job->>'lease')::uuid,true);
 foreach result in array array['"accepted"'::jsonb,'"rejected"'::jsonb,'"published"'::jsonb] loop
  perform public.distribution_queue_developer_email(submission,result#>>'{}','event-fixture:'||(result#>>'{}'),'Fixture');
 end loop;
 if (select count(*) from game_submission_notifications where submission_id=submission and event_key like 'event-fixture:%' and notification->>'recipient'='professional@example.test')<>3 then raise exception 'Destinataire des décisions incorrect';end if;
 perform public.distribution_queue_developer_email(submission,'correction','correction-fixture','Fix');
 update developer_contacts set contact_email='next@example.test' where user_id=actor;
 if (public.distribution_developer_email_status(actor)->>'verified')::boolean then raise exception 'Vérification conservée après changement';end if;
 if public.distribution_claim_submission_email_events(submission) is not null then raise exception 'Décision envoyée à une ancienne adresse';end if;
 if not exists(select 1 from game_submission_notifications where submission_id=submission and event_key='received' and message='{"text":"confidential frozen"}'::jsonb and sent_at is not null) then raise exception 'Événement historique réécrit';end if;
 if jsonb_array_length(public.distribution_developer_workspace(actor,game)->'builds')<>1 then raise exception 'Historique inaccessible après invalidation';end if;
 reset role;
 if (select count(*) from game_submissions where id=submission)<>1 or (select count(*) from games where id=game)<>1 then raise exception 'Historique supprimé';end if;
 -- Les quotas survivent aux renvois, changements d'adresse et codes consommés.
 update developer_email_challenges set created_at=clock_timestamp()-interval '61 seconds' where user_id=actor;
 select email_revision into revision from developer_contacts where user_id=actor;
 result:=public.distribution_reserve_developer_email(actor,gen_random_uuid(),revision,repeat('a',64),repeat('b',64),encrypted);
 update developer_contacts set contact_email='another@example.test' where user_id=actor;
 if public.distribution_confirm_developer_email(actor,(result->'challenge'->>'id')::uuid,repeat('b',64))->>'verified'<>'false' then raise exception 'Ancien code valide pour une nouvelle adresse';end if;
 select email_revision into revision from developer_contacts where user_id=actor;
 update developer_email_challenges set created_at=clock_timestamp()-interval '61 seconds' where user_id=actor;
 begin perform public.distribution_reserve_developer_email(actor,gen_random_uuid(),revision,repeat('a',64),repeat('b',64),encrypted);raise exception 'Quota horaire contourné';exception when raise_exception then if sqlerrm<>'rate_limited' then raise;end if;end;
 begin perform public.distribution_reserve_developer_email(other_actor,gen_random_uuid(),(select email_revision from developer_contacts where user_id=other_actor),repeat('a',64),repeat('b',64),encrypted);raise exception 'Quota destination contourné';exception when raise_exception then if sqlerrm<>'rate_limited' then raise;end if;end;
 update developer_email_challenges set created_at=clock_timestamp()-interval '2 hours' where user_id=actor;
 for i in 1..7 loop insert into developer_email_challenges(id,user_id,email_revision,destination_hash,created_at,expires_at) values(gen_random_uuid(),actor,revision,repeat('a',64),clock_timestamp()-interval '3 hours',clock_timestamp()-interval '2 hours');end loop;
 begin perform public.distribution_reserve_developer_email(actor,gen_random_uuid(),revision,repeat('a',64),repeat('b',64),encrypted);raise exception 'Quota journalier contourné';exception when raise_exception then if sqlerrm<>'rate_limited' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',actor::text,true);set local role authenticated;
 begin update developer_contacts set email_verified_at=now() where user_id=actor;raise exception 'Preuve falsifiée';exception when insufficient_privilege then null;end;
 begin perform * from developer_email_challenges;raise exception 'Codes exposés';exception when insufficient_privilege then null;end;
 begin perform public.distribution_confirm_developer_email(actor,second,repeat('b',64));raise exception 'RPC accessible au navigateur';exception when insufficient_privilege then null;end;
 reset role;
 perform public.distribution_cleanup_developer_email();
 if exists(select 1 from developer_email_challenges where code_hash is not null and expires_at<=clock_timestamp()) then raise exception 'Hash expiré conservé';end if;
end $$;
rollback;
